text:
{
  "osszkep": "A szöveg összességében tiszta, közvetlen és jól felépített, de néhány helyen túlságosan szakzsargonos, darabos vagy feleslegesen bürokratikus. Kis simításokkal még melegebb, gördülékenyebb és természetesebben kimondható lesz.",
  "javaslatok": [
    {
      "id": "L01",
      "gond": "A 'telepítetted az alkalmazásunkat' kicsit idegenül, gépiesen cseng; a szabályzat szerint érdemes simán 'az alkalmazás'-t mondani a birtokos forma helyett.",
      "uj_szoveg": "Köszönjük, hogy letöltötted az alkalmazást!"
    },
    {
      "id": "L04",
      "gond": "A 'maguktól megjönnek' kifejezés pongyola és kissé furcsán hat egy pénzügyi szolgáltatás narrációjában.",
      "uj_szoveg": "A számláid automatikusan megérkeznek a NAV-tól."
    },
    {
      "id": "L07",
      "gond": "A 'bekötés' belső szakmai szleng, egy átlagos felhasználónak nem mond semmit. Az 'elindulás' vagy 'beállítás' sokkal természetesebb.",
      "uj_szoveg": "A beállítás csak néhány egyszerű lépés. Mindegyiknél pontosan leírtuk, mit kell tenned."
    },
    {
      "id": "L11",
      "gond": "A 'megadod a kártyádat' kissé nyers, nem hozza a megbízható privátbanki nyugalmat.",
      "uj_szoveg": "Ezután elfogadod a szerződést, és megadod a bankkártyaadataidat a havidíjhoz."
    },
    {
      "id": "L12",
      "gond": "Az előző sor utáni ismétlés ('kártya'), illetve a hangnem kissé rideg.",
      "uj_szoveg": "Új vállalkozás esetén az adatokat csak akkor kérjük, ha már megkaptad az adószámodat."
    },
    {
      "id": "L15",
      "gond": "A 'személyidet és a lakcímkártyád lakcímes oldalát' kifejezés nyakatekert és nehezen kimondható beszédben.",
      "uj_szoveg": "Lefotózod a személyi igazolványodat és a lakcímkártyádat."
    },
    {
      "id": "L16",
      "gond": "A megfogalmazás hivatali, kissé fenyegető hangulatú.",
      "uj_szoveg": "Erre a törvény kötelez minket, hogy biztonságban tudhassuk a fiókodat."
    },
    {
      "id": "L17",
      "gond": "A 'beköti a számláidat' műszaki zsargon, félreérthető (a bankszámlára vagy a NAV-számlákra utal?).",
      "uj_szoveg": "Végül a könyvelőd összeköti a számlázódat a rendszerrel."
    },
    {
      "id": "L18",
      "gond": "A 'funkció zárva van' kifejezés magyartalan és technikai jellegű.",
      "uj_szoveg": "Addig néhány funkció még nem elérhető, de utána minden megnyílik."
    },
    {
      "id": "L20",
      "gond": "A 'huszonnégy-negyvennyolc órán belül' túl hivatalos és rideg határidő egy segítőkész szakasznál.",
      "uj_szoveg": "Ha elakadsz, kérj visszahívást, és csapatunk egy-két munkanapon belül felhív."
    }
  ]
}
